CREATE TABLE COMPANIA(CODIGO INTEGER PRIMARY KEY,NOMBRE VARCHAR(80),RNC_NUMERO VARCHAR(11),CALLEYNUMERO VARCHAR(100));
CREATE TABLE PROVEEDORES(CODIGO_CTE INTEGER PRIMARY KEY,DESCRIPCION VARCHAR(80),RNC_PROVEEDOR VARCHAR(11),CALYYNUM VARCHAR(100),EMAIL VARCHAR(100));
CREATE TABLE PRODUCTOS(CODIGO INTEGER PRIMARY KEY,DESCRIPCION VARCHAR(80));
CREATE TABLE TRANS_OPERACION_MASTER(NUMERO INTEGER PRIMARY KEY,CIA_KEY INTEGER,TIPO_CF VARCHAR(2),ECF VARCHAR(13),FECHA TIMESTAMP,MONTO NUMERIC(18,2),OBSERVACION VARCHAR(100),IND_MONTO_GRAVADO INTEGER,COD_PROVEEDOR INTEGER);
CREATE TABLE TRANS_OPERACION_DET(NUMERO INTEGER,SERIE INTEGER,COD_SERV_PROD INTEGER,OBSERVACION VARCHAR(100),CANTIDAD NUMERIC(18,2),PRECIO NUMERIC(18,2),VALOR NUMERIC(18,2),MONTO_ITBIS NUMERIC(18,2),MONTO_ITBIS_RETENIDO NUMERIC(18,2),MONTO_ISR_RETENIDO NUMERIC(18,2),IND_BIEN_SERVICIO INTEGER,STATUS CHAR(1));
CREATE TABLE ECF_RESERVA(HASH_DOC VARCHAR(120) PRIMARY KEY,NCF VARCHAR(13),ESTADO VARCHAR(32),MENSAJE VARCHAR(1024),UPDATED_AT TIMESTAMP,CODIGO_SEGURIDAD VARCHAR(64),FECHA_FIRMA TIMESTAMP);
